<?php
namespace App\Http\Controllers;
use App\Models\{Appointment,Client,Service,Staff,StaffSchedule,Notification}; use Illuminate\Http\Request; use Carbon\Carbon;
class AppointmentController extends Controller {
 public function index(Request $r){$u=$r->user();$q=Appointment::with(['client','service','staff']);if($u->role==='stylist')$q->where('staff_id',$u->staff?->id?:0);if($r->date)$q->whereDate('appointment_date',$r->date);if($r->status)$q->where('status',$r->status);if($r->q)$q->whereHas('client',fn($x)=>$x->where('full_name','like','%'.$r->q.'%'));return view('appointments.index',['appointments'=>$q->orderByDesc('appointment_date')->orderBy('start_time')->paginate(15)->withQueryString()]);}
 public function create(){if(auth()->user()->role==='stylist')abort(403);return view('appointments.form',$this->lists()+['appointment'=>new Appointment]);}
 public function store(Request $r){if($r->user()->role==='stylist')abort(403);$d=$this->validated($r);$d=$this->calculateAndValidateSlot($d);$d['created_by']=$r->user()->id;$a=Appointment::create($d);$this->notify($a,'New appointment','Appointment booked for '.$a->appointment_date->format('d M Y').' at '.substr($a->start_time,0,5));return redirect()->route('appointments.index')->with('success','Appointment booked successfully.');}
 public function edit(Appointment $appointment){$this->authorizeStylist($appointment);return view('appointments.form',$this->lists()+compact('appointment'));}
 public function update(Request $r,Appointment $appointment){$this->authorizeStylist($appointment);if($r->user()->role==='stylist'){$d=$r->validate(['status'=>'required|in:pending,confirmed,completed,no_show','notes'=>'nullable|string|max:2000']);$appointment->update($d);}else{$d=$this->validated($r);$d=$this->calculateAndValidateSlot($d,$appointment->id);$appointment->update($d);}$this->notify($appointment,'Appointment updated','Appointment schedule/status was updated.');return redirect()->route('appointments.index')->with('success','Appointment updated.');}
 public function destroy(Appointment $appointment){if(request()->user()->role==='stylist')abort(403);$appointment->update(['status'=>'cancelled']);$this->notify($appointment,'Appointment cancelled','Appointment #'.$appointment->id.' was cancelled.');return back()->with('success','Appointment cancelled.');}
 public function calendar(Request $r){$q=Appointment::with(['client','service','staff'])->whereBetween('appointment_date',[now()->startOfMonth()->subMonth(),now()->endOfMonth()->addMonth()]);if($r->user()->role==='stylist')$q->where('staff_id',$r->user()->staff?->id?:0);return view('appointments.calendar',['appointments'=>$q->get()]);}
 private function lists(){return ['clients'=>Client::orderBy('full_name')->get(),'services'=>Service::where('active',true)->orderBy('name')->get(),'staffMembers'=>Staff::with('services')->where('active',true)->orderBy('full_name')->get()];}
 private function validated(Request $r){return $r->validate(['client_id'=>'required|exists:clients,id','service_id'=>'required|exists:services,id','staff_id'=>'required|exists:staff,id','appointment_date'=>'required|date','start_time'=>'required|date_format:H:i','status'=>'required|in:pending,confirmed,completed,cancelled,no_show','notes'=>'nullable|string|max:2000']);}
 private function calculateAndValidateSlot(array $d,?int $ignore=null){$service=Service::findOrFail($d['service_id']);$staff=Staff::with('services')->findOrFail($d['staff_id']);if(!$staff->active)throw \Illuminate\Validation\ValidationException::withMessages(['staff_id'=>'Selected stylist is inactive.']);if(!$staff->services->contains($service->id))throw \Illuminate\Validation\ValidationException::withMessages(['staff_id'=>'This stylist is not assigned to the selected service.']);$start=Carbon::parse($d['appointment_date'].' '.$d['start_time']);$end=$start->copy()->addMinutes($service->duration_minutes);$dow=$start->dayOfWeek;$schedule=StaffSchedule::where('staff_id',$staff->id)->where('day_of_week',$dow)->first();if(!$schedule)throw \Illuminate\Validation\ValidationException::withMessages(['appointment_date'=>'Stylist is not scheduled to work on this day.']);$workStart=Carbon::parse($d['appointment_date'].' '.$schedule->start_time);$workEnd=Carbon::parse($d['appointment_date'].' '.$schedule->end_time);if($start->lt($workStart)||$end->gt($workEnd))throw \Illuminate\Validation\ValidationException::withMessages(['start_time'=>'Appointment falls outside stylist working hours ('.substr($schedule->start_time,0,5).'–'.substr($schedule->end_time,0,5).').']);$clash=Appointment::where('staff_id',$staff->id)->whereDate('appointment_date',$d['appointment_date'])->whereNotIn('status',['cancelled'])->when($ignore,fn($q)=>$q->where('id','!=',$ignore))->where('start_time','<',$end->format('H:i:s'))->where('end_time','>',$start->format('H:i:s'))->exists();if($clash)throw \Illuminate\Validation\ValidationException::withMessages(['start_time'=>'This stylist already has an overlapping appointment.']);$d['end_time']=$end->format('H:i:s');return $d;}
 private function authorizeStylist(Appointment $a){$u=request()->user();if($u->role==='stylist'&&$a->staff_id!==$u->staff?->id)abort(403);}
 private function notify(Appointment $a,string $title,string $msg){$a->loadMissing('staff.user');if($a->staff?->user_id)Notification::create(['user_id'=>$a->staff->user_id,'title'=>$title,'message'=>$msg,'type'=>'appointment']);}
}
